import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { randomUUID } from "node:crypto";
import {
  AUTHORITY, MANAGED, PHASES, authority, digest, includes, keyOf, readBytes, relativeName, replaceBytes,
  replaceWithHistory, text, workspaceRoot,
} from "./policy.mjs";
import {
  QUALITY, citesFile, claimRow, deliveryQuality, lineList, numericChecks,
  rejectedClaims, reviewedQuality, supplementChecks,
} from "./preflight.mjs";

export const name = "building-loop-governance";
export const inject = ["agents", "subagents", "systemPrompt", "tools"];
const WORKFLOW = "building_loop";
const FILE = "building_loop_file";
const EMPTY = { read: [], write: [] };

const BEGIN = {
  dispatch: "intake",
  "review-ready": "first-review",
  "supplement-ready": "supplement",
  "final-review-ready": "final-review",
};

const RULES = {
  intake: "接单。按指定二级索引找到候选。第一轮只做任务单允许的工作，保留送审原稿。读回候选后用 building_loop 的 submit 交接，证据不足则用 block。宿主通知总控。",
  "first-review": "首次验收。独立打开候选和每条引用的原文，核数字、行号和适用范围。无出处或原文不支持就填 unsupported，不代为补查。",
  supplement: "补查。读退回回执，用 building_loop 的 preflight 获取脚本复算和待改项。读原始材料，按证据原位修订，保留编号，出处路径和原文行写在同一行，例如 第 2-3 行。修改后完整读回，submit 带 quality 的六项说明。未修复的退回项或复算不符会被拦住。",
  "final-review": "终审。回到修订稿和原始证据，重新核对所有断言与改动。只有所有要求都支持才关单。",
};
const REVIEW_FORMAT = '用 building_loop 的 review 交 checks，回执由宿主写入。支持项填 id、status="supported"、file=原文项目相对路径、start/end=实际读过的原文首末行、basis=理由。缺源或不支持填 id、status="unsupported"、basis=原因，若无编号行另填 line；退回事实时只交 checks。事实都支持后再交 qualityChecks，六项分别填写 {pass: 布尔值, basis: 独立判断依据}。';
const QUALITY_RULE = "质量说明按任务规模写，小任务每项一两句具体内容。资料标实际来源及未证事项，结论和方法交代边界与取舍，给一个可行备选，先摘要后证据并留一句大白话。必要时引用文件和行号，细节留在正文，回执不用重复全文或哈希。";
const COORDINATOR = {
  dispatch: "派单。确认任务、单元与范围，advance 签发接单。",
  "review-ready": "接单方已交付。advance 发起首次独立核验。",
  "supplement-ready": "核验退回。依据回执用 advance 发起补查，默认续用执行会话。",
  "final-review-ready": "补查已交付。advance 发起终审。",
  blocked: "先确认回执的解阻条件，再用 advance 恢复原阶段。",
  closed: "单元已验收关单。读通过回执、核对执行身份并更新授权台账。汇报先给结论，再按需展开出处、方法、备选和未证边界，最后一句大白话。",
};

const string = { type: "string" };
const number = { type: "integer" };
const isReview = phase => phase.endsWith("review");
const buffer = value => Buffer.from(JSON.stringify(value, null, 2) + "\n", "utf8");

function tool(name, description, action, properties, execute) {
  return {
    name, description,
    parameters: {
      type: "object",
      properties: { action: { type: "string", enum: action }, ...properties },
      required: ["action"],
      additionalProperties: false,
    },
    output: {
      schema: { type: "object" },
      render: (_args, result) => [{ type: "text", text: JSON.stringify(result) }],
    },
    isConcurrencySafe: () => false,
    async execute(args, exec) {
      return JSON.parse(JSON.stringify(await execute(args, exec)));
    },
  };
}

function requireText(value, label, limit = 1200) {
  if (typeof value !== "string" || !value.trim() || value.length > limit) throw new Error("需要" + label);
  return value.trim();
}

function unitOf(frame, id) {
  if (!Object.hasOwn(frame.policy.units, id)) throw new Error("该工作单元未获授权");
  return frame.policy.units[id];
}

function viewUnits(frame) {
  return Object.keys(frame.policy.units).map(id => {
    const unit = Object.hasOwn(frame.state.units, id) ? frame.state.units[id] : undefined;
    if (!unit) return { unit: id, phase: "dispatch", next: "intake" };
    const { phase, executor, reviewer, receipt, unsupported, qualityRejected, blocked } = unit;
    return {
      unit: id, phase, executor, reviewer, receipt, unsupported, qualityRejected, blocked,
      next: phase === "blocked" ? unit.resumePhase : BEGIN[phase],
      owned: unit.owner === frame.agent.id,
    };
  });
}

export function apply(ctx, config = {}) {
  const presetId = config.presetId ?? "building-loop";
  const hostHome = path.resolve(process.env.DSH_HOME || path.join(os.homedir(), ".dsh"));
  const stateHome = path.join(hostHome, "building-loop-state");
  fs.mkdirSync(stateHome, { recursive: true });

  function scope(agent) {
    if (!agent || ctx.agents.get(agent.id) !== agent) throw new Error("只接受当前 DSH 会话的调用");
    const root = workspaceRoot(agent.session.header.cwd, hostHome);
    const policy = authority(root);
    const file = digest(keyOf(root)) + ".json";
    const old = readBytes(stateHome, file);
    let state = old ? JSON.parse(text(old)) : { spec: "building-loop-state/1", policy: policy.hash, units: {}, markers: {} };
    if (state.spec !== "building-loop-state/1") throw new Error("工作台账版本无效");
    if (state.policy !== policy.hash) {
      if (Object.values(state.units).some(unit => unit.phase !== "closed")) throw new Error("运行期间授权清单发生变化，需项目维护者核对");
      state = { ...state, policy: policy.hash, units: {} };
    }
    state.units = Object.assign(Object.create(null), state.units);
    state.markers = Object.assign(Object.create(null), state.markers);
    const parent = agent.session.header.parentSession;
    const child = parent !== undefined || agent.session.header.origin === "subagent";
    let assignment;
    if (child) {
      assignment = Object.entries(state.units).find(([, unit]) =>
        unit.owner === parent && unit.actor === agent.id && PHASES.includes(unit.phase));
    }
    const role = child ? !assignment ? "idle" : isReview(assignment[1].phase) ? "reviewer" : "executor" : "coordinator";
    const grant = assignment ? unitOf({ policy }, assignment[0]).phases[assignment[1].phase] : child ? EMPTY : policy.coordinator;
    const reads = role === "idle" ? [] : [...new Set([...grant.read, ...policy.instructions])];
    return { agent, root, policy, file, old, state, role, assignment, reads, writes: grant.write };
  }

  function change(agent, operation) {
    const info = scope(agent);
    const lock = path.join(stateHome, info.file + ".lock");
    let fd;
    try { fd = fs.openSync(lock, "wx", 0o600); }
    catch (error) {
      if (error.code === "EEXIST") throw new Error("工作台账正在更新，请按当前台账重试");
      throw error;
    }
    try {
      const frame = scope(agent);
      if (frame.file !== info.file) throw new Error("工作区在动作前发生变化");
      const result = operation(frame);
      if (frame.changed) replaceBytes(stateHome, frame.file, buffer(frame.state), frame.old);
      return result;
    } finally {
      fs.closeSync(fd);
      fs.unlinkSync(lock);
    }
  }

  function tag(frame) {
    if (frame.assignment) {
      const [id, unit] = frame.assignment;
      return unit.owner + "/" + id + "/" + unit.serial + "/" + unit.phase;
    }
    return frame.agent.id + "/coordinator/" + Object.values(frame.state.units)
      .map(unit => unit.serial + "-" + unit.phase).join("_");
  }

  function fileAction(args, exec) {
    return change(exec.agent, frame => {
      if (frame.role === "idle") throw new Error("当前子会话没有已授权的工作阶段");
      if (args.action === "list") return { read: frame.reads, write: frame.writes };
      if (args.action === "search") {
        const query = requireText(args.query, "搜索字面量", 120);
        const paths = args.path === undefined ? frame.reads : [relativeName(args.path)];
        const matches = [];
        for (const file of paths) {
          if (!includes(frame.reads, file)) throw new Error("该文件不在当前读白名单");
          const bytes = readBytes(frame.root, file);
          if (!bytes) continue;
          const lines = lineList(bytes);
          for (let i = 0; i < lines.length && matches.length < 40; i++) {
            if (lines[i].includes(query)) matches.push({ path: file, line: i + 1, text: lines[i].slice(0, 800) });
          }
          if (matches.length >= 40) break;
        }
        return { matches };
      }
      const file = relativeName(args.path);
      if (args.action === "write") {
        if (!includes(frame.writes, file)) throw new Error("该文件不在当前写白名单");
        if (typeof args.content !== "string") throw new Error("需要 UTF-8 正文");
        const note = requireText(args.note, "改动理由", 500);
        const result = replaceWithHistory(frame.root, file, args.content, note, tag(frame), frame.state.markers);
        frame.changed = result.changed;
        return result;
      }
      if (!includes(frame.reads, file)) throw new Error("该文件不在当前读白名单");
      if (args.action === "history") {
        const history = readBytes(frame.root, MANAGED + "/changes/" + file + ".md");
        return { path: file, recent: history ? lineList(history).slice(0, 12) : [] };
      }
      if (args.action !== "read") throw new Error("未知文件动作");
      const bytes = readBytes(frame.root, file);
      if (!bytes) throw new Error("授权文件目前不存在");
      const lines = lineList(bytes);
      const start = args.start ?? 1;
      const count = args.count ?? 150;
      if (!Number.isSafeInteger(start) || start < 1 || !Number.isSafeInteger(count) || count < 1 || count > 250) {
        throw new Error("行范围无效，单次最多 250 行");
      }
      if (frame.assignment && start <= lines.length) {
        const active = frame.assignment[1];
        const key = keyOf(file);
        const hash = digest(bytes);
        const coverage = Object.hasOwn(active.seen, key) ? active.seen[key] : undefined;
        const ranges = coverage?.hash === hash ? coverage.ranges : [];
        const end = Math.min(start + count - 1, lines.length);
        Object.defineProperty(active.seen, key, { value: { hash, ranges: mergeRanges([...ranges, [start, end]]) },
          configurable: true, enumerable: true, writable: true });
        frame.changed = true;
      }
      return { path: file, totalLines: lines.length, sha256: digest(bytes),
        lines: lines.slice(start - 1, start - 1 + count).map((line, index) => [start + index, line]) };
    });
  }

  function prepare(frame, id) {
    if (frame.role !== "coordinator") throw new Error("只有总控可以推进阶段");
    const spec = unitOf(frame, id);
    const prior = Object.hasOwn(frame.state.units, id) ? frame.state.units[id] : null;
    if (prior && prior.owner !== frame.agent.id) throw new Error("此工作单元由其他总控持有");
    if (Object.entries(frame.state.units).some(([key, unit]) => key !== id && unit.phase !== "closed")) {
      throw new Error("当前工作区另有未结单的单元");
    }
    const phase = prior?.phase === "blocked" ? prior.resumePhase : BEGIN[prior?.phase ?? "dispatch"];
    if (!phase) throw new Error("当前阶段尚未交付或已经关单");
    const role = isReview(phase) ? "reviewer" : "executor";
    const reusable = prior?.phase === "blocked" ? prior.actor
      : phase === "supplement" && spec.continuation === "fresh" ? undefined : prior?.[role];
    return { prior, phase, role, reusable, serial: (prior?.serial ?? 0) + 1 };
  }

  async function advance(args, exec) {
    const agent = exec.agent;
    const id = args.unit;
    const prepared = prepare(scope(agent), id);
    const resident = prepared.reusable && ctx.agents.get(prepared.reusable);
    if (resident) await waitIdle(resident, exec.signal);
    exec.signal.throwIfAborted();
    const childId = prepared.reusable ?? randomUUID();
    const next = change(agent, frame => {
      const plan = prepare(frame, id);
      if (plan.phase !== prepared.phase || plan.serial !== prepared.serial || plan.reusable !== prepared.reusable) {
        throw new Error("工作单元已经由其他调用推进");
      }
      const record = {
        ...(plan.prior ?? {}), owner: agent.id, actor: childId, [plan.role]: childId,
        phase: plan.phase, serial: plan.serial, seen: {},
      };
      delete record.blocked;
      delete record.resumePhase;
      const spec = unitOf(frame, id);
      if (plan.phase === "supplement" && record.unsupported?.length && !record.rejected) {
        const candidate = readBytes(frame.root, spec.candidate);
        if (!candidate) throw new Error("无法为旧退回记录建立候选基线");
        record.rejected = rejectedClaims(frame.root, spec, lineList(candidate),
          record.unsupported.map(id => ({ id })), spec.phases.supplement.read);
      }
      frame.state.units[id] = record;
      frame.changed = true;
      const brief = "工作单元 " + id + " 进入 " + plan.phase + "。候选文件 " + spec.candidate
        + (record.receipt && plan.phase === "supplement" ? "。请读取退回回执 " + record.receipt : "")
        + "。执行前依据已注入的阶段规则与授权范围。"
        + (args.note === undefined ? "" : "\n本次任务要求 " + requireText(args.note, "任务说明"));
      return { workspace: frame.root, phase: plan.phase, serial: plan.serial, brief };
    });
    const content = [{ type: "text", text: next.brief }];
    try {
      if (prepared.reusable) {
        await ctx.subagents.sendMessage(agent, childId, content, { signal: exec.signal });
      } else {
        const selection = agent.model.current();
        await ctx.subagents.startActivation({
          provider: "spawn", childId, label: id + " " + next.phase,
          delivery: "parent", signal: exec.signal,
          request: {
            parent: agent, cwd: next.workspace, agentPreset: presetId, prompt: content, maxDepth: 1,
            ...(selection ? { agentOptions: selection } : {}),
          },
        });
      }
    } catch (error) {
      change(agent, frame => {
        const record = frame.state.units[id];
        if (record?.actor === childId && record.phase === next.phase && record.serial === next.serial) {
          if (prepared.prior) frame.state.units[id] = prepared.prior;
          else delete frame.state.units[id];
          frame.changed = true;
        }
      });
      throw error;
    }
    return { unit: id, phase: next.phase, childId, reused: Boolean(prepared.reusable) };
  }

  function report(args, exec) {
    return change(exec.agent, frame => {
      if (!frame.assignment) throw new Error("当前会话没有可交付阶段");
      const [id, active] = frame.assignment;
      if (args.unit !== id) throw new Error("当前会话无该单元的权限");
      const spec = unitOf(frame, id);
      if (args.action === "block") {
        active.blocked = requireText(args.note, "阻塞原因、责任人和恢复条件");
        active.resumePhase = active.phase;
        active.phase = "blocked";
      } else if (args.action === "submit" && frame.role === "executor") {
        const bytes = readBytes(frame.root, spec.candidate);
        if (!bytes) throw new Error("候选文件尚未交付");
        const seen = active.seen[keyOf(spec.candidate)];
        if (seen?.hash !== digest(bytes) || !seen.ranges.some(([a, b]) => a === 1 && b >= lineList(bytes).length)) {
          throw new Error("请先完整读回当前候选文件");
        }
        if (active.phase === "supplement") {
          const preflight = supplementChecks(frame.root, spec, lineList(bytes), frame.reads, active);
          if (!preflight.ok) throw new Error("[building-loop/preflight] " + preflight.issues.join("；"));
          active.quality = deliveryQuality(args.quality, active.quality, active.qualityRejected);
          active.phase = "final-review-ready";
        } else {
          active.phase = "review-ready";
        }
      } else if (args.action === "review" && frame.role === "reviewer") {
        const grant = spec.phases[active.phase];
        const bytes = readBytes(frame.root, spec.candidate);
        const lines = bytes && lineList(bytes);
        let checked = reviewChecks(frame, active, spec, grant, args.checks, bytes, lines);
        const calculations = checked.every(check => check.status === "supported")
          ? numericChecks(frame.root, spec, lines, frame.reads) : [];
        const mismatches = new Map(calculations.filter(result => !result.ok).map(result => [result.id, result.issue]));
        checked = checked.map(check => mismatches.has(check.id)
          ? { ...check, status: "unsupported", basis: "脚本复算未通过 " + mismatches.get(check.id) } : check);
        const unsupported = checked.filter(check => check.status !== "supported").map(check => check.id);
        const qualityChecks = !unsupported.length || args.qualityChecks !== undefined ? reviewedQuality(args.qualityChecks) : null;
        const qualityRejected = qualityChecks ? Object.keys(qualityChecks).filter(field => !qualityChecks[field].pass) : [];
        const decision = unsupported.length || qualityRejected.length ? "reject" : "accept";
        active.rejected = rejectedClaims(frame.root, spec, lines, checked.filter(check => check.status !== "supported"), frame.reads);
        const receipt = {
          unit: id, phase: active.phase, reviewer: exec.agent.id, decision, unsupported, qualityRejected, checks: checked, calculations,
          ...(active.quality ? { quality: active.quality } : {}),
          ...(qualityChecks ? { qualityChecks } : {}),
        };
        replaceWithHistory(frame.root, grant.receipt, text(buffer(receipt)), "独立核验 " + decision,
          tag(frame), frame.state.markers);
        active.receipt = grant.receipt;
        active.unsupported = unsupported;
        active.qualityRejected = qualityRejected;
        active.phase = decision === "accept" ? "closed" : "supplement-ready";
        if (decision === "accept") delete active.quality;
      } else {
        throw new Error("当前角色和阶段不允许此动作");
      }
      active.seen = {};
      frame.changed = true;
      return { unit: id, phase: active.phase, receipt: active.receipt, unsupported: active.unsupported,
        qualityRejected: active.qualityRejected, parent: active.owner };
    });
  }

  async function workflow(args, exec) {
    if (args.action === "status") {
      try {
        const frame = scope(exec.agent);
        if (frame.role === "coordinator") return { role: frame.role, units: viewUnits(frame), read: frame.reads, write: frame.writes };
        const assignment = frame.assignment;
        return { role: frame.role, unit: assignment?.[0], phase: assignment?.[1].phase, read: frame.reads, write: frame.writes };
      } catch (error) { return { blocked: String(error.message) }; }
    }
    if (args.action === "advance") return advance(args, exec);
    if (args.action === "preflight") {
      const frame = scope(exec.agent);
      const assignment = frame.assignment;
      if (!assignment || args.unit !== assignment[0] || assignment[1].phase !== "supplement") {
        throw new Error("只有本单元的补查执行方可预检");
      }
      const spec = unitOf(frame, args.unit);
      const bytes = readBytes(frame.root, spec.candidate);
      if (!bytes) throw new Error("候选文件尚未交付");
      return supplementChecks(frame.root, spec, lineList(bytes), frame.reads, assignment[1]);
    }
    const { parent, ...result } = report(args, exec);
    try {
      const notice = "building-loop 已落盘 " + JSON.stringify(result);
      await ctx.subagents.sendMessage(exec.agent, parent, [{ type: "text", text: notice }], { signal: exec.signal });
      return { ...result, notified: true };
    } catch {
      return { ...result, notified: false };
    }
  }

  const deny = exec => {
    if (exec.name === WORKFLOW || exec.name === FILE) return undefined;
    return "[building-loop/denied] 原生工具 " + exec.name + " 禁止直接调用。使用受控文件或派单入口";
  };
  ctx.tools.guard(deny);
  ctx.on("tools/pre-execute", (exec, next) => {
    const reason = deny(exec);
    return reason ? { kind: "deny", reason } : next();
  });
  ctx.on("agent/pre-step", async (_request, next) => {
    const decision = await next();
    if (decision.kind !== "enter") return decision;
    return { ...decision, messages: decision.messages.filter(message => message.source?.kind !== "agent-instructions") };
  });

  ctx.tools.register(tool(FILE, "按当前角色的准确路径白名单列出、读取、字面搜索或原子写入 UTF-8 文件。写入自动维护一份改前备份和逐文件日志。history 取授权文件的最近更新。", ["list", "read", "search", "write", "history"], {
    path: string, query: string, content: string, note: string, start: number, count: number,
  }, fileAction));

  const qualitySchema = assessment => ({
    type: "object",
    properties: Object.fromEntries(Object.entries(QUALITY).map(([key, description]) => [key,
      assessment ? { type: "object", description, properties: { pass: { type: "boolean" }, basis: string },
        required: ["pass", "basis"], additionalProperties: false } : { ...string, description },
    ])),
    required: Object.keys(QUALITY),
    additionalProperties: false,
  });
  ctx.tools.register(tool(WORKFLOW, "按状态派发、续用、交付和验收。advance 仅总控。preflight 和补查 submit 由执行方使用。review 仅核验方，提交逐条 checks 和独立质量判断，宿主写回执。", ["status", "advance", "preflight", "submit", "review", "block"], {
    unit: string, note: string,
    checks: { type: "array", items: {
      type: "object", properties: {
        id: string, status: { type: "string", enum: ["supported", "unsupported"] },
        line: { ...number, description: "退回项在候选中没有编号行时填写候选行号" },
        file: { ...string, description: "支持项必填。实际读取的原文项目相对路径" },
        start: { ...number, description: "支持项必填。原文起始行，1 起计" },
        end: { ...number, description: "支持项必填。原文结束行，1 起计" },
        basis: { ...string, description: "为何支持或为何不足" },
      }, required: ["id", "status", "basis"], additionalProperties: false,
    } },
    quality: qualitySchema(false),
    qualityChecks: qualitySchema(true),
  }, workflow));

  ctx.systemPrompt.context({
    name: "building-loop.phase", order: 130, required: true, interpolate: false,
    text({ agent, scope: owner }) {
      try {
        const frame = scope(agent ?? owner);
        const assignment = frame.assignment;
        const units = frame.role === "coordinator" ? viewUnits(frame) : null;
        const current = units?.find(unit => unit.owned && unit.phase !== "closed");
        const closed = units?.length && units.every(unit => unit.phase === "closed");
        const phase = assignment?.[1].phase ?? (units ? current?.phase ?? (closed ? "closed" : "dispatch") : "idle");
        const rule = frame.role === "coordinator"
          ? (COORDINATOR[phase] ?? "等待当前阶段交付或核验回执。") + " 总控只读写白名单内的中央文件和回执。"
          : RULES[phase] ?? "本子会话当前无工作授权，等待总控。";
        const descriptor = "building-loop role=" + frame.role + " phase=" + phase;
        if (frame.role === "idle") return descriptor + "\n" + rule;
        const shared = frame.policy.instructions.map(file => {
          const bytes = readBytes(frame.root, file, 12 * 1024);
          return bytes ? "项目规则 " + file + "\n" + text(bytes) : "";
        }).filter(Boolean);
        const detail = assignment ? {
          unit: assignment[0], candidate: unitOf(frame, assignment[0]).candidate, receipt: assignment[1].receipt,
          ...(frame.role === "reviewer" ? { claims: unitOf(frame, assignment[0]).claims } : {}),
          ...(phase === "final-review" && assignment[1].quality ? { executionQuality: assignment[1].quality } : {}),
        } : units;
        return [descriptor, rule, ...(frame.role === "reviewer" ? [REVIEW_FORMAT] : []),
          ...(phase === "supplement" || frame.role === "reviewer" ? [QUALITY_RULE] : []), "工具仅 building_loop 和 building_loop_file。",
          JSON.stringify({ read: frame.reads, write: frame.writes, detail }), ...shared].join("\n");
      } catch (error) {
        return "building-loop role=blocked phase=authority\n" + error.message + "。请项目维护者核对 " + AUTHORITY + "。";
      }
    },
  });
}

function mergeRanges(ranges) {
  const merged = [];
  for (const [start, end] of ranges.sort((left, right) => left[0] - right[0])) {
    const last = merged.at(-1);
    if (last && start <= last[1] + 1) last[1] = Math.max(last[1], end);
    else merged.push([start, end]);
  }
  return merged;
}

function reviewChecks(frame, active, spec, grant, checks, bytes, candidate) {
  const seen = active.seen[keyOf(spec.candidate)];
  if (!candidate || seen?.hash !== digest(bytes) || !seen.ranges.some(([a, b]) => a === 1 && b >= candidate.length)) {
    throw new Error("验收前须完整读取当前候选正文");
  }
  if (!Array.isArray(checks) || checks.length > 64) throw new Error("核验须逐条提交检查结果");
  const byId = new Map();
  for (const check of checks) {
    const id = check?.id;
    if (typeof id !== "string" || !/^[A-Za-z0-9_-]{1,48}$/.test(id) || byId.has(id)
      || spec.claims.length && !spec.claims.includes(id)) throw new Error("核验编号无效、重复或超范围");
    byId.set(id, check);
  }
  const ids = spec.claims.length ? spec.claims : [...byId.keys()];
  if (!ids.length) throw new Error("至少需要一项核验结果");
  return ids.map(id => {
    const check = byId.get(id);
    if (!check) return { id, status: "unsupported", basis: "缺少核验结果" };
    const basis = requireText(check.basis, "核验依据", 600);
    const reject = Number.isSafeInteger(check.line) ? { id, status: "unsupported", line: check.line } : { id, status: "unsupported" };
    if (check.status !== "supported") return { ...reject, basis };
    const fail = reason => ({ ...reject, basis: reason + "。" + basis });
    let file;
    try { file = relativeName(check.file); }
    catch { throw new Error(id + " 的支持项需要有效的原文路径"); }
    if (!includes(grant.evidence, file)) return fail("出处不在核验授权范围");
    const evidence = readBytes(frame.root, file);
    const coverage = active.seen[keyOf(file)];
    if (!evidence || coverage?.hash !== digest(evidence) || !Number.isSafeInteger(check.start) || !Number.isSafeInteger(check.end)
      || check.start < 1 || check.end < check.start || !coverage.ranges.some(([a, b]) => a <= check.start && b >= check.end)) {
      throw new Error(id + " 的原文行未读、行号无效或来源已变，请读取后重新核验");
    }
    let line = Number.isSafeInteger(check.line) ? check.line : null;
    if (spec.claims.length) {
      const row = claimRow(candidate, id);
      if (!row || !citesFile(row.body, file)) {
        return fail("候选断言行缺少对应出处");
      }
      line = row.line;
    }
    return { id, status: "supported", file, line, start: check.start, end: check.end, sha256: digest(evidence), basis };
  });
}

async function waitIdle(agent, signal) {
  const bounded = AbortSignal.any([signal, AbortSignal.timeout(20000)]);
  bounded.throwIfAborted();
  let abort;
  try {
    await Promise.race([agent.whenIdle(), new Promise((_, reject) => {
      abort = () => reject(bounded.reason);
      bounded.addEventListener("abort", abort, { once: true });
    })]);
  } finally { if (abort) bounded.removeEventListener("abort", abort); }
}

import fs from "node:fs";
import path from "node:path";
import { createHash, randomUUID } from "node:crypto";

export const AUTHORITY = "BUILDING-LOOP.json";
export const MANAGED = ".building-loop";
export const PHASES = ["intake", "first-review", "supplement", "final-review"];
const LIMIT = 256 * 1024;

export const digest = bytes => createHash("sha256").update(bytes).digest("hex");
export const keyOf = value => process.platform === "win32" ? value.toLowerCase() : value;

export function relativeName(value, internal = false) {
  if (typeof value !== "string" || !value || value.length > 500) throw new Error("需要明确的项目相对文件路径");
  const parts = value.replaceAll("\\", "/").split("/");
  if (parts.some(part => !part || part === "." || part === ".." || /[:*?"<>|\x00-\x1f]|[. ]$/.test(part)
    || /^(?:con|prn|aux|nul|com[0-9¹²³]|lpt[0-9¹²³])(?:\.|$)/i.test(part))) {
    throw new Error("拒绝绝对路径、通配符、路径别名和上级目录");
  }
  const first = parts[0].toLowerCase();
  if (!internal && [AUTHORITY.toLowerCase(), MANAGED, ".git"].includes(first)) throw new Error("授权文件和运行记录由宿主管理");
  return parts.join("/");
}

function stat(file) {
  try { return fs.lstatSync(file); }
  catch (error) { if (error.code === "ENOENT") return null; throw error; }
}

export function workspaceRoot(value, hostHome) {
  if (typeof value !== "string" || !path.isAbsolute(value)) throw new Error("请先选择本地项目目录");
  const root = fs.realpathSync.native(value);
  if (!stat(root)?.isDirectory()) throw new Error("工作区需要是本地目录");
  const home = fs.realpathSync.native(hostHome);
  const overlap = (a, b) => {
    const relative = path.relative(a, b);
    return relative === "" || !path.isAbsolute(relative) && !relative.startsWith(".." + path.sep) && relative !== "..";
  };
  if (overlap(root, home) || overlap(home, root)) throw new Error("工作区不能与 DSH 数据目录重叠");
  return root;
}

function resolveFile(root, name, createParents = false) {
  const parts = relativeName(name, true).split("/");
  let file = root;
  for (let i = 0; i < parts.length; i++) {
    file = path.join(file, parts[i]);
    const final = i === parts.length - 1;
    let entry = stat(file);
    if (!entry && !final && createParents) {
      try { fs.mkdirSync(file); }
      catch (error) { if (error.code !== "EEXIST") throw error; }
      entry = stat(file);
    }
    if (!entry) {
      if (!final) return { file: path.join(root, ...parts), entry: null };
      return { file, entry: null };
    }
    if (entry.isSymbolicLink() || keyOf(fs.realpathSync.native(file)) !== keyOf(file)
      || (final ? !entry.isFile() || entry.nlink !== 1 : !entry.isDirectory())) {
      throw new Error("拒绝链接、硬链接、路径别名和非普通文件");
    }
  }
  return { file, entry: stat(file) };
}

export function readBytes(root, name, limit = LIMIT) {
  const { file, entry } = resolveFile(root, name);
  if (!entry) return null;
  if (entry.size > limit) throw new Error("文件超过受控工具的大小上限");
  const fd = fs.openSync(file, fs.constants.O_RDONLY | (fs.constants.O_NOFOLLOW ?? 0));
  try {
    const opened = fs.fstatSync(fd);
    if (opened.dev !== entry.dev || opened.ino !== entry.ino || opened.nlink !== 1 || !opened.isFile() || opened.size > limit) {
      throw new Error("文件身份在读取前发生变化");
    }
    const bytes = Buffer.alloc(limit + 1);
    let size = 0;
    while (size < bytes.length) {
      const count = fs.readSync(fd, bytes, size, bytes.length - size, null);
      if (!count) break;
      size += count;
    }
    if (size > limit) throw new Error("文件超过受控工具的大小上限");
    return bytes.subarray(0, size);
  } finally {
    fs.closeSync(fd);
  }
}

export function text(bytes) {
  return new TextDecoder("utf-8", { fatal: true }).decode(bytes);
}

export function equal(left, right) {
  return left === null ? right === null : right !== null && left.equals(right);
}

export function replaceBytes(root, name, bytes, before) {
  const { file } = resolveFile(root, name, bytes !== null);
  if (bytes === null) {
    if (!equal(readBytes(root, name), before)) throw new Error("文件在写入前发生变化");
    if (before !== null) fs.unlinkSync(file);
    return;
  }
  if (bytes.length > LIMIT) throw new Error("内容超过受控工具的大小上限");
  const temp = path.join(path.dirname(file), ".building-loop-write-" + randomUUID());
  let staged = false;
  try {
    const fd = fs.openSync(temp, "wx", 0o600);
    staged = true;
    try {
      fs.writeFileSync(fd, bytes);
      fs.fsyncSync(fd);
    } finally { fs.closeSync(fd); }
    if (!equal(readBytes(root, name), before)) throw new Error("文件在写入前发生变化");
    fs.renameSync(temp, file);
    staged = false;
  } finally { if (staged) fs.unlinkSync(temp); }
}

function pathList(value = []) {
  if (!Array.isArray(value) || value.length > 80) throw new Error("授权文件须为路径数组");
  const paths = value.map(item => relativeName(item));
  if (new Set(paths.map(keyOf)).size !== paths.length) throw new Error("授权文件路径重复");
  return paths;
}

function object(value, label, fields) {
  if (!value || typeof value !== "object" || Array.isArray(value)) throw new Error(label + "须为对象");
  if (fields && Object.keys(value).some(name => !fields.includes(name))) throw new Error(label + "包含未知字段");
  return value;
}

function grants(value, label, fields = []) {
  object(value, label, ["read", "write", ...fields]);
  return { read: pathList(value.read), write: pathList(value.write) };
}

export function includes(paths, name) {
  return paths.some(item => keyOf(item) === keyOf(name));
}

export function authority(root) {
  const bytes = readBytes(root, AUTHORITY, 64 * 1024);
  if (!bytes) throw new Error("需要项目维护者配置 " + AUTHORITY);
  const source = object(JSON.parse(text(bytes)), "授权文件", ["spec", "instructions", "coordinator", "units"]);
  if (source.spec !== "building-loop/1") throw new Error("不支持的授权文件版本");
  const coordinator = grants(source.coordinator, "总控");
  const instructions = pathList(source.instructions);
  if (instructions.length > 3 || instructions.some(file => !includes(coordinator.read, file) || includes(coordinator.write, file))) {
    throw new Error("注入的项目规则须在总控只读授权中，最多三份");
  }
  const units = Object.create(null);
  const mutable = [...coordinator.write];
  const receiptsSeen = new Set();
  for (const [id, value] of Object.entries(object(source.units, "工作单元"))) {
    if (!/^[A-Za-z][A-Za-z0-9_-]{0,47}$/.test(id) || Object.keys(units).length >= 80) throw new Error("工作单元编号或数量无效");
    object(value, "工作单元", ["candidate", "claims", "continuation", "phases", "calculations"]);
    const candidate = relativeName(value.candidate);
    const claims = value.claims ?? [];
    if (!Array.isArray(claims) || claims.length > 64 || claims.some(claim => typeof claim !== "string" || !/^[A-Za-z0-9_-]{1,48}$/.test(claim))
      || new Set(claims).size !== claims.length) throw new Error("断言编号无效或重复");
    const continuation = value.continuation ?? "reuse";
    if (!["reuse", "fresh"].includes(continuation)) throw new Error("未知续派方式");
    const phases = Object.create(null);
    object(value.phases, "阶段", PHASES);
    for (const phase of PHASES) {
      const review = phase.endsWith("review");
      const raw = value.phases[phase];
      const access = grants(raw, phase, review ? ["receipt", "evidence"] : []);
      if (!includes(access.read, candidate)) throw new Error("当前阶段需要候选文件读权");
      if (review) {
        if (access.write.length) throw new Error("核验方只读，回执由机制写入");
        const receipt = relativeName(raw.receipt);
        if (receiptsSeen.has(keyOf(receipt))) throw new Error("核验回执路径重复");
        receiptsSeen.add(keyOf(receipt));
        const evidence = pathList(raw.evidence);
        if (includes([...access.read, ...instructions], receipt)
          || evidence.some(file => !includes(access.read, file) || keyOf(file) === keyOf(candidate))) {
          throw new Error("核验回执与候选、证据和规则文件必须分开");
        }
        phases[phase] = { ...access, receipt, evidence };
      } else {
        phases[phase] = access;
      }
    }
    if (includes(coordinator.write, candidate) || PHASES.some(phase => phases[phase].write.some(file => includes(coordinator.write, file)))) {
      throw new Error("总控和执行方的写入授权须分开");
    }
    mutable.push(...PHASES.flatMap(phase => phases[phase].write));
    const calculations = Object.create(null);
    for (const [claim, formula] of Object.entries(object(value.calculations ?? {}, "复算规则"))) {
      if (!claims.includes(claim)) throw new Error("复算规则须绑定已登记的断言编号");
      object(formula, "复算规则", ["kind", "source", "keyColumn", "valueColumn", "before", "after", "decimals"]);
      const { kind, keyColumn, valueColumn, before, after, decimals = 2 } = formula;
      const source = relativeName(formula.source);
      if (kind !== "percent-decrease" || !Number.isSafeInteger(decimals) || decimals < 0 || decimals > 6
        || [keyColumn, valueColumn, before, after].some(item => typeof item !== "string" || !item.trim() || item.length > 80)
        || keyColumn === valueColumn || before === after) throw new Error("无效的 CSV 降幅复算规则");
      if (!includes(phases.supplement.read, source) || !includes(phases["final-review"].evidence, source)) {
        throw new Error("复算原始文件须在补查读授权和终审证据授权内");
      }
      calculations[claim] = { kind, source, keyColumn, valueColumn, before, after, decimals };
    }
    units[id] = { candidate, claims, continuation, phases, calculations };
  }
  const protectedFiles = [...instructions, ...Object.values(units).flatMap(unit => [
    unit.phases["first-review"].receipt, unit.phases["final-review"].receipt,
    ...unit.phases["first-review"].evidence, ...unit.phases["final-review"].evidence,
  ])];
  if (mutable.some(file => includes(protectedFiles, file))) throw new Error("指令、原始证据和核验回执不能授予模型写权");
  return { hash: digest(bytes), coordinator, instructions, units };
}

export function replaceWithHistory(root, file, content, note, tag, markers) {
  const before = readBytes(root, file);
  const after = Buffer.from(content, "utf8");
  if (equal(before, after)) return { path: file, changed: false, sha256: digest(after) };
  const log = MANAGED + "/changes/" + file + ".md";
  const backup = MANAGED + "/latest_backup/" + file;
  const oldLog = readBytes(root, log);
  const summary = note.trim().replace(/\s+/g, " ").slice(0, 500);
  const record = "- " + new Date().toISOString() + " " + tag + " " + summary + " SHA-256 " + digest(after) + "\n";
  const history = Buffer.from(record + (oldLog ? text(oldLog) : ""), "utf8");
  if (history.length > LIMIT || after.length > LIMIT) throw new Error("内容或更新日志超过受控工具的大小上限");
  const marker = keyOf(file);
  if (markers[marker] !== tag) {
    if (before) replaceBytes(root, backup, before, readBytes(root, backup));
    if (oldLog) {
      const logBackup = MANAGED + "/latest_backup/" + log;
      replaceBytes(root, logBackup, oldLog, readBytes(root, logBackup));
    }
  }
  replaceBytes(root, log, history, oldLog);
  try { replaceBytes(root, file, after, before); }
  catch (error) {
    replaceBytes(root, log, oldLog, history);
    throw error;
  }
  markers[marker] = tag;
  return { path: file, changed: true, sha256: digest(after), log, ...(before ? { backup } : {}) };
}

import { digest, includes, keyOf, readBytes, text } from "./policy.mjs";

export const QUALITY = {
  sources: "资料的原始出处、核实办法和仍待证的部分",
  conclusion: "可支持的结论、修订理由与适用范围",
  method: "采用的方法、复算或反查及其局限",
  alternatives: "可行的备选、取舍和更合适的提议",
  detail: "先摘要后依据的层次、读者需要的细节",
  plain: "面向读者的一句大白话",
};

export const lineList = bytes => text(bytes).split(/\r\n|\n|\r/);
const escape = value => value.replace(/[|\\{}()[\]^$+*?.-]/g, "\\$&");

export function claimRow(lines, id) {
  const pattern = new RegExp("^\\s*(?:[-*]\\s+|\\d+[.)]\\s+)?(?:\\*\\*)?" + escape(id) + "(?:\\*\\*)?\\s*[:：]\\s*(.*)$");
  const found = [];
  for (let i = 0; i < lines.length; i++) {
    const match = pattern.exec(lines[i]);
    if (match) found.push({ line: i + 1, body: match[1] });
  }
  return found.length === 1 ? found[0] : null;
}

function citation(body, file) {
  const pattern = new RegExp("(^|[\\s:：\\x60\"'“‘(（\\[【〔<《,，、])" + escape(file)
    + "(?=$|[\\s#:,：，、。；;\\x60\"'”’）)\\]】〕>》]|\\.(?:\\s|$))", process.platform === "win32" ? "i" : "");
  const row = body.replaceAll("\\", "/");
  const match = pattern.exec(row);
  if (!match) return null;
  const after = row.slice(match.index + match[0].length);
  const range = /^\s*(?:\x60\s*)?(?:#L(\d+)(?:-L?(\d+))?|[:：](\d+)(?:[-–—](\d+))?|第\s*(\d+)(?:\s*[-–—、至到]\s*(\d+))?\s*行)/i.exec(after);
  if (!range) return { start: null, end: null };
  const start = Number(range[1] ?? range[3] ?? range[5]);
  const end = Number(range[2] ?? range[4] ?? range[6] ?? start);
  return Number.isSafeInteger(start) && Number.isSafeInteger(end) && start > 0 && end >= start ? { start, end } : null;
}

export const citesFile = (body, file) => citation(body, file) !== null;

function conclusion(body) {
  return body.normalize("NFKC").replaceAll("−", "-").split(/\s*[（(〔【\[]?\s*(?:出处|来源|证据|source|evidence)\s*[:：]/i, 1)[0];
}

function normalized(body) {
  return body.normalize("NFKC").replace(/[\s,，。;；!?“”‘’\x60*_()\[\]【】〔〕]+/g, "").toLowerCase();
}

function shape(root, spec, row, readable, seen) {
  const refs = [];
  for (const file of spec.phases["final-review"].evidence) {
    const locate = citation(row.body, file);
    if (!locate?.start || !includes(readable, file)) continue;
    const bytes = readBytes(root, file);
    if (!bytes || locate.end > lineList(bytes).length) continue;
    const hash = digest(bytes);
    const observed = seen?.[keyOf(file)];
    if (seen && (observed?.hash !== hash || !observed.ranges.some(([a, b]) => a <= locate.start && b >= locate.end))) continue;
    refs.push({ hash, start: locate.start, end: locate.end });
  }
  return { conclusion: digest(normalized(conclusion(row.body))), refs };
}

export function rejectedClaims(root, spec, lines, rejected, readable) {
  return Object.fromEntries(rejected.map(check => {
    const row = claimRow(lines, check.id) ?? (Number.isSafeInteger(check.line) && check.line > 0 && check.line <= lines.length
      ? { body: lines[check.line - 1] } : null);
    if (!row) throw new Error(check.id + " 的退回项缺少可定位的候选行，请提供编号行或候选行号");
    return [check.id, shape(root, spec, row, readable)];
  }));
}

function decimal(value) {
  const parsed = /^([+-]?)(\d{1,18})(?:\.(\d{1,9}))?$/.exec(value);
  if (!parsed) throw new Error("原始数值需要普通十进制数字");
  const fraction = parsed[3] ?? "";
  return { n: BigInt(parsed[2] + fraction) * (parsed[1] === "-" ? -1n : 1n), scale: 10n ** BigInt(fraction.length) };
}

function equalNumber(left, right) {
  const a = decimal(left);
  const b = decimal(right);
  return a.n * b.scale === b.n * a.scale;
}

function formatDecimal(n, places) {
  const prefix = n < 0n ? "-" : "";
  const digits = (n < 0n ? -n : n).toString().padStart(places + 1, "0");
  if (!places) return prefix + digits;
  return (prefix + digits.slice(0, -places) + "." + digits.slice(-places)).replace(/0+$/, "").replace(/\.$/, "");
}

function calculate(bytes, rule) {
  const lines = lineList(bytes);
  if (lines.some(line => line.includes('"'))) throw new Error("复算支持无引号和无跨行字段的 UTF-8 CSV");
  const header = lines[0].split(",").map(x => x.trim());
  const key = header.indexOf(rule.keyColumn);
  const value = header.indexOf(rule.valueColumn);
  if (key < 0 || value < 0 || new Set(header).size !== header.length) throw new Error("复算 CSV 表头不匹配或有重复列");
  const rows = new Map();
  for (let i = 1; i < lines.length; i++) {
    if (!lines[i].trim()) continue;
    const cells = lines[i].split(",").map(x => x.trim());
    if (cells.length !== header.length) throw new Error("复算 CSV 行列数量不一致");
    if (cells[key] !== rule.before && cells[key] !== rule.after) continue;
    if (rows.has(cells[key])) throw new Error("复算 CSV 匹配到重复数据行");
    rows.set(cells[key], { raw: cells[value], line: i + 1 });
  }
  const before = rows.get(rule.before);
  const after = rows.get(rule.after);
  if (!before || !after) throw new Error("缺少配置的基准行或对照行");
  const a = decimal(before.raw);
  const b = decimal(after.raw);
  if (a.n <= 0n || b.n < 0n) throw new Error("降幅复算需要正基准和非负对照值");
  const numerator = (a.n * b.scale - b.n * a.scale) * 100n * 10n ** BigInt(rule.decimals);
  const denominator = a.n * b.scale;
  const absolute = numerator < 0n ? -numerator : numerator;
  const rounded = ((2n * absolute + denominator) / (2n * denominator)) * (numerator < 0n ? -1n : 1n);
  return { expected: formatDecimal(rounded, rule.decimals), before, after };
}

export function numericChecks(root, spec, lines, readable) {
  return Object.entries(spec.calculations).map(([id, rule]) => {
    try {
      if (!includes(readable, rule.source)) throw new Error("本阶段没有原始数据的读取授权");
      const bytes = readBytes(root, rule.source);
      if (!bytes) throw new Error("复算原始文件尚未提供");
      const { expected, before, after } = calculate(bytes, rule);
      const row = claimRow(lines, id);
      const cites = row && citation(row.body, rule.source);
      const percentages = row ? [...conclusion(row.body).matchAll(/(?<![\dA-Za-z.,+\-])([+-]?\d+(?:\.\d+)?)\s*%/g)].map(x => x[1]) : [];
      const correct = percentages.length > 0 && percentages.every(value => equalNumber(value, expected));
      const coversRows = cites?.start && cites.start <= Math.min(before.line, after.line)
        && cites.end >= Math.max(before.line, after.line) && cites.end <= lineList(bytes).length;
      const issue = !correct ? "结论中的降幅应为 " + expected + "%"
        : !coversRows ? "出处须引用 " + rule.source + " 中两条原始数据行" : null;
      return {
        id, ok: issue === null, issue, expected: expected + "%", reported: percentages.map(value => value + "%"),
        source: rule.source, sourceHash: digest(bytes), before, after, formula: "(基准-对照)/基准×100",
      };
    } catch (error) { return { id, ok: false, source: rule.source, issue: error.message }; }
  });
}

export function supplementChecks(root, spec, lines, readable, active) {
  const issues = [];
  for (const id of active.unsupported ?? []) {
    const before = active.rejected?.[id];
    const row = claimRow(lines, id);
    if (!before) {
      issues.push(id + " 缺少退回基线，先记录阻塞并由总控重新发起补查");
      continue;
    }
    if (!row) {
      issues.push(id + " 需要保留唯一的编号断言行");
      continue;
    }
    const now = shape(root, spec, row, readable, active.seen);
    if (before.conclusion === now.conclusion && !now.refs.some(ref => !before.refs.some(old =>
      ref.hash === old.hash && old.start <= ref.start && old.end >= ref.end))) {
      issues.push(id + " 的退回结论与可定位证据均未变");
    }
  }
  const calculations = numericChecks(root, spec, lines, readable);
  for (const result of calculations) if (!result.ok) issues.push(result.id + " " + result.issue);
  return { ok: issues.length === 0, issues, calculations };
}

function qualityText(value, field) {
  if (typeof value !== "string" || !value.trim() || /^(?:已核对|已检查|已优化|完成|通过|无|同上|ok|pass|n\/a)[。.!！]?$/i.test(value.trim())) {
    throw new Error("请给出质量项 " + field + " 的具体内容或适用边界");
  }
  if (value.length > 4000) throw new Error("质量项 " + field + " 超过 4000 字，请保留关键判断和证据路径");
  return value.trim();
}

export function deliveryQuality(value, previous, rejected = []) {
  return Object.fromEntries(Object.keys(QUALITY).map(field => {
    const note = qualityText(value?.[field], field);
    if (rejected.includes(field) && normalized(note) === normalized(previous?.[field] ?? "")) {
      throw new Error("退回的质量项 " + field + " 没有修订");
    }
    return [field, note];
  }));
}

export function reviewedQuality(value) {
  return Object.fromEntries(Object.keys(QUALITY).map(field => {
    if (typeof value?.[field]?.pass !== "boolean") throw new Error("验收须逐项给出质量判断 " + field);
    return [field, { pass: value[field].pass, basis: qualityText(value[field].basis, field) }];
  }));
}

import fs from "node:fs";
import path from "node:path";
import { randomUUID } from "node:crypto";

export const name = "building-loop-real-audit-witness";
export const inject = ["agentPresets", "agents", "sessions", "sessionController", "tools", "llm", "systemPrompt"];

const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));
const home = process.env.BUILDING_LOOP_REAL_RUN;
const presetId = process.env.BUILDING_LOOP_GOV_PRESET ?? "building-loop";
const route = { provider: "deepseek-official", model: "deepseek-flash", reasoningEffort: "off" };
const tracked = new Set([
  "turn/start", "turn/end", "step/start", "step/end", "user/message",
  "assistant/message", "assistant/attempt", "tool/call", "tool/result",
  "subagent/catalog", "subagent/descriptor", "agent/inbox/claimed",
  "agent/inbox/inserted", "session/model",
]);
const allowed = new Set(["read", "write", "edit", "skill", "subagent", "send_message",
  "list_agents", "wait_agent", "list_subagent_models", "todo_write", "glob", "grep", "pwsh", "building_loop", "building_loop_file"]);


function json(data) {
  const key = process.env.DEEPSEEK_API_KEY;
  const text = JSON.stringify(data, (_key, value) => typeof value === "bigint" ? value.toString() : value);
  return key ? text.replaceAll(key, "[redacted]") : text;
}

function append(name, data) {
  fs.appendFileSync(path.join(home, name), json({ time: Date.now(), ...data }) + "\n", "utf8");
}

function finished(data) {
  fs.writeFileSync(path.join(home, "finished.json"), json(data) + "\n", "utf8");
}

function inside(root, target) {
  const relative = path.relative(root, target);
  return relative !== ".." && !relative.startsWith(".." + path.sep) && !path.isAbsolute(relative);
}

export function apply(ctx) {
  const groups = new Map();
  const identities = new Map();
  let active = null;
  let initiated = false;
  const progress = data => append("progress.jsonl", data);
  const scopeOf = sessionId => identities.get(sessionId) ?? active;

  ctx.on("llm/stream", (options, next) => {
    const sid = options.sessionId;
    const group = groups.get(scopeOf(sid));
    if (sid && group) {
      const payload = JSON.stringify(options.messages);
      const marker = [...payload.matchAll(/building-loop role=([a-z-]+) phase=([a-z-]+)/g)].at(-1);
      append("events.jsonl", { group: group.name, sid, type: "fixture/request", data: {
        role: marker?.[1], phase: marker?.[2],
        unapprovedInstruction: payload.includes("TEST_ONLY_UNAUTHORIZED_INSTRUCTION_96CD8A"),
      } });
    }
    return next();
  });

  ctx.on("session/event", (session, event) => {
    if (!tracked.has(event.type)) return;
    const label = scopeOf(session.id);
    const group = groups.get(label);
    if (!group) return;
    identities.set(session.id, label);
    group.ids.add(session.id);
    group.lastEvent = Date.now();
    const data = event.type === "assistant/message"
      ? { turn: event.data.turn, step: event.data.step, usage: event.data.usage,
          source: { provider: event.data.message?.source?.provider, model: event.data.message?.source?.model },
          content: event.data.message?.content?.filter(block => block.type !== "thinking") }
      : event.type === "assistant/attempt"
        ? { turn: event.data.turn, step: event.data.step, stream: event.data.stream }
        : event.data;
    append("events.jsonl", { group: label, sid: session.id, seq: event.seq, type: event.type, data });
    if (event.type === "tool/result" && !group.released) {
      const receipt = path.join(group.workspace, "records", "audit-first.json");
      try {
        if (fs.existsSync(receipt) && JSON.parse(fs.readFileSync(receipt, "utf8").replace(/^\uFEFF/, "")).decision === "reject") {
          fs.copyFileSync(path.join(home, "sealed-timing.csv"), path.join(group.workspace, "module", "timing.csv"), fs.constants.COPYFILE_EXCL);
          group.released = true;
          append("events.jsonl", { group: label, sid: session.id, type: "fixture/evidence-released", data: { after: "audit-first reject" } });
          progress({ group: label, event: "first-rejection-observed" });
        }
      } catch (error) {
        if (!(error instanceof SyntaxError)) progress({ group: label, event: "fixture-error", error: String(error) });
      }
    }
    if (event.type === "step/start") group.steps++;
    if (event.type === "subagent/catalog") {
      identities.set(event.data.childId, label);
      group.ids.add(event.data.childId);
      progress({ group: label, event: "child", sid: event.data.childId, label: event.data.label });
    }
    if (event.type === "turn/end") {
      const reason = event.data?.reason?.kind ?? "unknown";
      if (reason === "error" || reason === "blocked" || reason === "max-tokens") {
        progress({ group: label, event: "turn-end", sid: session.id, reason, detail: event.data?.reason?.code });
      }
    }
  });

  async function allIdle(group) {
    const agents = [...group.ids].map(id => ctx.agents.get(id)).filter(Boolean);
    return Promise.race([Promise.all(agents.map(agent => agent.whenIdle())).then(() => true), sleep(550).then(() => false)]);
  }

  async function rawProbes(agent, group) {
    const candidate = path.join(group.workspace, "module", "candidate.md");
    const before = fs.readFileSync(candidate);
    const cases = [
      ["glob", { pattern: "**/*" }, false],
      ["grep", { pattern: "25%", path: group.workspace }, false],
      ["read", { file_path: candidate }, false],
      ["write", { file_path: candidate, content: "SHOULD_NOT_WRITE" }, false],
      ["edit", { file_path: candidate, old_string: "25%", new_string: "999%" }, false],
      ["pwsh", { command: "Get-Content -LiteralPath module/candidate.md", description: "Synthetic scope probe" }, false],
      ["building_loop_file", { action: "read", path: "module/candidate.md" }, false],
      ["building_loop_file", { action: "write", path: "module/candidate.md", content: "SHOULD_NOT_WRITE", note: "probe" }, false],
      ["building_loop_file", { action: "search", path: "module/candidate.md", query: "25%" }, false],
      ["building_loop_file", { action: "read", path: "PROJECT.md" }, true],
      ["building_loop_file", { action: "search", query: "功能回归通过" }, true],
      ["building_loop_file", { action: "read", path: "records/../module/candidate.md" }, false],
      ["building_loop_file", { action: "write", path: "BUILDING-LOOP.json", content: "{}", note: "probe" }, false],
      ["building_loop", { action: "submit", unit: "K01" }, false],
    ];
    for (const [tool, args, expect] of cases) {
      const result = await ctx.tools.execute({
        agent, calls: [{ type: "tool-call", id: randomUUID(), name: tool, arguments: JSON.stringify(args) }],
        signal: AbortSignal.timeout(8000), maxParallelToolCalls: 1,
      });
      const response = result.results[0]?.result;
      const success = response !== undefined && !response.isError;
      const summary = JSON.stringify(response?.content);
      append("events.jsonl", { group: group.name, sid: agent.id, type: "fixture/raw-probe",
        data: { tool, args, expect, success, response: summary } });
      if (success !== expect || expect && tool === "building_loop_file" && args.action === "search" && summary.includes("25%")) {
        throw new Error("Tool scope probe failed for " + tool + " " + summary?.slice(0, 180));
      }
      if (!expect && !tool.startsWith("building_loop") && tool !== "edit" && !summary.includes("building-loop/denied")) {
        throw new Error("Native tool did not reach governance denial: " + tool + " " + summary?.slice(0, 180));
      }
    }
    if (!before.equals(fs.readFileSync(candidate))) throw new Error("Scope probe modified the candidate");
    progress({ group: group.name, event: "raw-probes-passed", count: cases.length });
  }

  async function runGroup(name, onlyProbe = false) {
    const directory = path.join(home, name);
    const group = { name, workspace: path.join(directory, "workspace"), ids: new Set(), steps: 0, lastEvent: Date.now() };
    groups.set(name, group);
    active = name;
    const started = Date.now();
    const { sessionId } = await ctx.sessionController.create({ cwd: group.workspace, agentPreset: presetId });
    group.root = sessionId;
    group.ids.add(sessionId);
    identities.set(sessionId, name);
    const agent = ctx.agents.get(sessionId);
    const prompt = await ctx.systemPrompt.assemble({ agent, scope: agent });
    const context = prompt.contexts.find(entry => entry.name === "building-loop.phase");
    if (!context?.text.includes("role=coordinator phase=dispatch")) throw new Error("Governed preset has no dispatch phase");
    await rawProbes(agent, group);
    if (onlyProbe) {
      const standard = await ctx.sessionController.create({ cwd: group.workspace, agentPreset: "standard" });
      const other = ctx.agents.get(standard.sessionId);
      const reason = ctx.tools.checkGuards({ agent: other, name: "read", arguments: { file_path: "PROJECT.md" } });
      if (String(reason).includes("building-loop/denied")) throw new Error("Guard leaked into the standard preset");
      return { group: name, status: "probed", standardUnaffected: true };
    }
    await ctx.sessionController.selectModel({ sessionId, ...route });
    const declared = ctx.tools.schemas(agent).map(definition => definition.name);
    progress({ group: name, event: "start", sid: sessionId, tools: declared.filter(tool => allowed.has(tool)) });
    const requestId = randomUUID();
    await ctx.sessionController.prompt({
      sessionId, requestId, clientTimeZone: "Asia/Shanghai",
      content: [{ type: "text", text: fs.readFileSync(path.join(directory, "prompt.txt"), "utf8") }],
    }, AbortSignal.timeout(10000));
    let end = "deadline";
    while (Date.now() - started < 260000) {
      if (group.steps > 80) {
        end = "step-budget";
        break;
      }
      if (await allIdle(group)) {
        const finalPath = path.join(group.workspace, "records", "audit-final.json");
        const hasFinal = fs.existsSync(finalPath) && JSON.parse(fs.readFileSync(finalPath, "utf8")).decision === "accept";
        const hasLedger = fs.existsSync(path.join(group.workspace, "ledger.md"));
        if (hasFinal && hasLedger && Date.now() - group.lastEvent > 1800) {
          end = "artifacts-present";
          break;
        }
        if (Date.now() - group.lastEvent > 14000) {
          end = "idle-without-all-artifacts";
          break;
        }
      }
      await sleep(600);
    }
    const result = { group: name, event: "finish", sid: sessionId, end, wallMs: Date.now() - started,
      steps: group.steps, members: [...group.ids] };
    progress(result);
    fs.writeFileSync(path.join(directory, "host-result.json"), json(result) + "\n", "utf8");
    active = null;
    if (end === "deadline" || end === "step-budget") throw new Error(name + " exceeded its test budget");
    return result;
  }

  const timer = setInterval(async () => {
    if (initiated) return;
    try {
      const preset = (await ctx.agentPresets.list()).find(row => row.id === presetId);
      if (!preset) return;
      initiated = true;
      if (preset.broken) throw new Error("building-loop preset is broken");
      if (process.env.BUILDING_LOOP_GOV_PROBE === "1") {
        finished(await runGroup("reuse", true));
        return;
      }
      const info = await ctx.llm.resolveModelInfo(route.provider, route.model);
      progress({ event: "route-ready", provider: route.provider, model: route.model, title: info?.name });
      const reuse = await runGroup("reuse");
      if (reuse.steps === 0) throw new Error("No model step ran in the first arm");
      const fresh = await runGroup("fresh");
      finished({ status: "observed", groups: [reuse, fresh] });
    } catch (error) {
      initiated = true;
      progress({ event: "error", error: String(error) });
      finished({ status: "error", error: String(error) });
    }
  }, 300);
  ctx.on("dispose", () => clearInterval(timer));
}
